insert into public.autocompletion(id,type,label,workspace_id,department,commune,institution_type,source_url,address_keywords,order_index)
select gen_random_uuid()::text,'institution',e.label,'workspace_default',e.department,e.commune,e."institutionType",e.source,'[]',
  (select coalesce(max(order_index),-1) from public.autocompletion where type='institution' and workspace_id='workspace_default') + row_number() over(order by e.label)
from jsonb_to_recordset($new$[{"label":"Hôpital Universitaire de Mirebalais","department":"Centre","commune":"Mirebalais","institutionType":"Hôpital Universitaire","source":"https://www.mspp.gouv.ht/site/downloads/Realisations%20MSPP%202011%202014%20avec%20appui%20partenaires%2014%20sept%2014.pdf"},{"label":"Hôpital Sacré-Cœur de Milot","department":"Nord","commune":"Milot","institutionType":"Hôpital","source":"https://www.mspp.gouv.ht/site/downloads/GR%20tome%202.pdf"},{"label":"Hôpital Albert Schweitzer","department":"Artibonite","commune":"Verrettes","institutionType":"Hôpital","source":"https://mspp.gouv.ht/site/downloads/inst_artibonites.pdf"}]$new$::jsonb) as e(label text,department text,commune text,"institutionType" text,source text)
where exists(select 1 from public.workspaces where id='workspace_default')
and not exists(select 1 from public.autocompletion a where a.type='institution' and a.workspace_id='workspace_default' and institution_private.normalized_name(a.label)=institution_private.normalized_name(e.label));
